<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import { useWalletMarketing } from '../useWalletMarketing'
import WalletOfferEditor from '../components/WalletOfferEditor.vue'
import { dateTime } from '../format'
const {t}=useI18n(),{store,can,context,busy,error,settings,campaigns,ready,status,reason,editing,form,more,permitted,load,saveSettings,edit,save,action}=useWalletMarketing()
</script>
<template><section class="wallet-page-heading"><h2>{{t('wallet.marketing.marketing')}}</h2><button :disabled="busy" @click="load()">{{t('wallet.refresh')}}</button></section><p v-if="error" class="wallet-error" role="alert">{{error}}</p><p v-if="!permitted()" class="wallet-empty">{{t('wallet.noRights')}}</p><p v-else-if="busy&&!ready" role="status">{{t('wallet.loading')}}</p><template v-if="permitted()"><form v-if="settings&&can('wallet.marketing.manage')" class="wallet-form" @submit.prevent="saveSettings"><h3>{{t('wallet.marketing.settings')}}</h3><WalletOfferEditor v-model="settings.baseOffers" base /><label>{{t('wallet.marketing.policy')}}<select v-model="settings.deductionPolicy"><option v-for="policy in ['proportional','principal_first']" :key="policy" :value="policy">{{t(`wallet.marketing.${policy}`)}}</option></select></label><label><input v-model="settings.campaignsEnabled" type="checkbox">{{t('wallet.marketing.campaignsEnabled')}}</label><label><input v-model="settings.selfServiceEnabled" type="checkbox">{{t('wallet.marketing.selfService')}}</label><label><input v-model="settings.pointsEnabled" type="checkbox">{{t('wallet.marketing.pointsEnabled')}}</label><p>{{t('wallet.marketing.affected')}}: {{settings.affectedStoreIds?.join(', ')}}</p><button :disabled="busy">{{t('wallet.save')}}</button></form><h3>{{t('wallet.marketing.campaigns')}}</h3><label>{{t('wallet.marketing.status')}}<select v-model="status" :disabled="busy" @change="load()"><option value="">{{t('wallet.marketing.all')}}</option><option v-for="state in ['draft','published','disabled','archived']" :key="state">{{t(`wallet.marketing.${state}`)}}</option></select></label><p v-if="ready&&!campaigns.length" class="wallet-empty">{{t('wallet.empty')}}</p><article v-for="c in campaigns" :key="c.id" class="wallet-card"><h3>{{c.name}}</h3><p>{{t(`wallet.marketing.${c.status}`)}} · {{t('wallet.marketing.version')}} {{c.version}}</p><p>{{dateTime(c.startsAt,context?.store.timezone??'Asia/Singapore')}} — {{dateTime(c.endsAt,context?.store.timezone??'Asia/Singapore')}}</p><template v-if="can('wallet.marketing.manage')"><button :disabled="busy||c.status==='archived'" @click="edit(c)">{{t('wallet.marketing.edit')}}</button><button :disabled="busy||c.status==='archived'||c.currentPublishedRevision===c.draftVersion" @click="action(c,'publish')">{{t('wallet.marketing.publish')}}</button><button :disabled="busy||!reason.trim()||c.status!=='published'" @click="action(c,'disable')">{{t('wallet.marketing.disable')}}</button><button :disabled="busy||!reason.trim()||c.status==='archived'" @click="action(c,'archive')">{{t('wallet.marketing.archive')}}</button></template></article><button v-if="more" :disabled="busy" @click="load(true)">{{t('wallet.marketing.next')}}</button><template v-if="can('wallet.marketing.manage')"><label>{{t('wallet.marketing.reason')}}<input v-model.trim="reason" maxlength="200"></label><form class="wallet-form" @submit.prevent="save"><h3>{{editing?t('wallet.marketing.edit'):t('wallet.marketing.create')}}</h3><button v-if="editing" type="button" @click="edit()">{{t('wallet.marketing.create')}}</button><label>{{t('wallet.marketing.name')}}<input v-model.trim="form.name" required maxlength="120"></label><label>{{t('wallet.marketing.startsAt')}}<input v-model="form.startsAt" type="datetime-local" required></label><label>{{t('wallet.marketing.endsAt')}}<input v-model="form.endsAt" type="datetime-local" required></label><label>{{t('wallet.marketing.priority')}}<input v-model.number="form.priority" type="number" required step="1"></label><label>{{t('wallet.marketing.terms')}}<textarea v-model.trim="form.terms" maxlength="2000" /></label><WalletOfferEditor v-model="form.offers" /><button :disabled="busy||!form.offers.length">{{t('wallet.marketing.save')}}</button></form></template></template></template>
